tool_args.command:
cd /tmp && rm -rf wh && mkdir wh && cd wh && python3 - <<'EOF'
import zipfile, glob, os
for w in glob.glob('/workspace/wheelhouse/*.whl'):
    d = os.path.basename(w)[:-4]
    zipfile.ZipFile(w).extractall(d)
    print("===", d)
    for root, dirs, files in os.walk(d):
        for f in files:
            print(os.path.join(root, f))
EOF
